import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.BU31gs4v.js";const m=JSON.parse('{"title":"《从 Letta Code 到 Mini-Letta：给 Agent 装上会成长的记忆》大纲","description":"","frontmatter":{},"headers":[],"relativePath":"OUTLINE.md","filePath":"OUTLINE.md","lastUpdated":1791479463000}'),l={name:"OUTLINE.md"};function o(h,a,n,d,c,s){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="《从-letta-code-到-mini-letta-给-agent-装上会成长的记忆》大纲" tabindex="-1">《从 Letta Code 到 Mini-Letta：给 Agent 装上会成长的记忆》大纲 <a class="header-anchor" href="#《从-letta-code-到-mini-letta-给-agent-装上会成长的记忆》大纲" aria-label="Permalink to &quot;《从 Letta Code 到 Mini-Letta：给 Agent 装上会成长的记忆》大纲&quot;">​</a></h1><blockquote><p>参照仓库：letta-ai/letta-code @ <code>70ead335</code>（只讲记忆子系统） 读者目标：读完能从零写出一个<strong>带长期记忆</strong>的 coding agent——记忆是 git 仓库里的 Markdown 文件，会被编译进系统提示，上下文满了会压缩，空闲时由后台“反思”子 agent 整理记忆。 写作方式：每章先读真源码（<code>path:line</code>），再在 mini-letta 里重写一遍；每个 Part 以一个 Lab 收尾，打一个 git tag。</p></blockquote><h2 id="贯穿全书的项目-mini-letta-typescript-bun" tabindex="-1">贯穿全书的项目：mini-letta（TypeScript + Bun） <a class="header-anchor" href="#贯穿全书的项目-mini-letta-typescript-bun" aria-label="Permalink to &quot;贯穿全书的项目：mini-letta（TypeScript + Bun）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>能力</th><th>章节</th></tr></thead><tbody><tr><td>v0.1</td><td>最小 agent loop（CLI）、mock LLM、两个静态记忆块拼进系统提示</td><td>1–3, Lab 1</td></tr><tr><td>v0.2</td><td>MemFS：每个 agent 一个 git 记忆仓库、v2 布局、文件工具、pre-commit 校验</td><td>4–7, Lab 2</td></tr><tr><td>v0.3</td><td>系统提示编译器、revision 缓存、对话中途 <code>&lt;memory_update&gt;</code></td><td>8–10, Lab 3</td></tr><tr><td>v0.4</td><td>token 预算、滑动窗口压缩、transcript 持久化与 recall 搜索</td><td>11–13, Lab 4</td></tr><tr><td>v0.5</td><td>后台反思：触发器、transcript 切片、worktree 隔离、合并状态机、写锁</td><td>14–17, Lab 5</td></tr><tr><td>v1.0</td><td>远端同步、多 agent 隔离、Memory Palace 网页查看器、端到端脚本</td><td>18–20, Lab 6</td></tr></tbody></table><p>技术栈：Bun + TypeScript、系统 <code>git</code>、readline CLI（替代 Ink TUI）、<code>Bun.serve</code> 做 Palace 页面； LLM 用确定性 <strong>mock provider</strong>（离线可跑，会发工具调用），另用 OpenAI 兼容接口对接本地 Ollama 做一次真模型验证。</p><h2 id="part-0-导读" tabindex="-1">Part 0 导读 <a class="header-anchor" href="#part-0-导读" aria-label="Permalink to &quot;Part 0 导读&quot;">​</a></h2><ul><li><a href="./chapters/00-how-to-read">第 0 章 本书怎么读</a></li></ul><h2 id="part-i-全景-浅" tabindex="-1">Part I 全景（浅） <a class="header-anchor" href="#part-i-全景-浅" aria-label="Permalink to &quot;Part I 全景（浅）&quot;">​</a></h2><ul><li><a href="./chapters/01-why-memory">第 1 章 Agent 为什么需要记忆</a></li><li><a href="./chapters/02-memory-map">第 2 章 letta-code 记忆子系统地图</a></li><li><a href="./chapters/03-life-of-a-memory">第 3 章 ★ 一条记忆的一生</a></li><li><a href="./chapters/lab-1-minimal-agent">Lab 1 mini-letta v0.1：能对话、记忆块进系统提示</a></li></ul><h2 id="part-ii-记忆即文件-memfs" tabindex="-1">Part II 记忆即文件：MemFS <a class="header-anchor" href="#part-ii-记忆即文件-memfs" aria-label="Permalink to &quot;Part II 记忆即文件：MemFS&quot;">​</a></h2><ul><li><a href="./chapters/04-blocks-to-files">第 4 章 从 memory block 到 memory file</a></li><li><a href="./chapters/05-memfs-v2-layout">第 5 章 MemFS v2 布局：常驻、按需与技能</a></li><li><a href="./chapters/06-git-as-memory">第 6 章 用 git 管记忆</a></li><li><a href="./chapters/07-gatekeepers">第 7 章 守门员：pre-commit hook、frontmatter 与预算</a></li><li><a href="./chapters/lab-2-memfs">Lab 2 mini-letta v0.2：记忆变成 git 仓库</a></li></ul><h2 id="part-iii-编译-从记忆到系统提示-★★" tabindex="-1">Part III 编译：从记忆到系统提示 ★★ <a class="header-anchor" href="#part-iii-编译-从记忆到系统提示-★★" aria-label="Permalink to &quot;Part III 编译：从记忆到系统提示 ★★&quot;">​</a></h2><ul><li><a href="./chapters/08-prompt-compiler">第 8 章 ★★ 系统提示编译器</a></li><li><a href="./chapters/09-when-to-recompile">第 9 章 ★★ 何时重编译：缓存、<code>&lt;memory_update&gt;</code> 与提醒</a></li><li><a href="./chapters/10-teaching-memory">第 10 章 教模型管理记忆：读一份系统提示</a></li><li><a href="./chapters/lab-3-living-persona">Lab 3 mini-letta v0.3：会成长的人格</a></li></ul><h2 id="part-iv-上下文窗口与-recall" tabindex="-1">Part IV 上下文窗口与 recall <a class="header-anchor" href="#part-iv-上下文窗口与-recall" aria-label="Permalink to &quot;Part IV 上下文窗口与 recall&quot;">​</a></h2><ul><li><a href="./chapters/11-context-budget">第 11 章 上下文预算：估算、阈值与“地板”</a></li><li><a href="./chapters/12-compaction">第 12 章 压缩：滑动窗口、摘要与上下文 id 列表</a></li><li><a href="./chapters/13-recall">第 13 章 Recall：找回被压缩掉的经历</a></li><li><a href="./chapters/lab-4-long-conversations">Lab 4 mini-letta v0.4：长对话不撑爆，也不失忆</a></li></ul><h2 id="part-v-睡眠时间-后台反思-★★" tabindex="-1">Part V 睡眠时间：后台反思 ★★ <a class="header-anchor" href="#part-v-睡眠时间-后台反思-★★" aria-label="Permalink to &quot;Part V 睡眠时间：后台反思 ★★&quot;">​</a></h2><ul><li><a href="./chapters/14-reflection-triggers">第 14 章 ★★ 睡眠时间：反思什么时候发生</a></li><li><a href="./chapters/15-reflection-subagent">第 15 章 ★★ 反思子 agent：读经历、写记忆</a></li><li><a href="./chapters/16-worktree-merge">第 16 章 ★★ worktree 隔离与合并状态机</a></li><li><a href="./chapters/17-concurrent-writers">第 17 章 并发写者：锁、worker 与冲突修复</a></li><li><a href="./chapters/lab-5-sleeptime">Lab 5 mini-letta v0.5：对话结束，后台反思</a></li></ul><h2 id="part-vi-平台化-深" tabindex="-1">Part VI 平台化（深） <a class="header-anchor" href="#part-vi-平台化-深" aria-label="Permalink to &quot;Part VI 平台化（深）&quot;">​</a></h2><ul><li><a href="./chapters/18-sync">第 18 章 同步与多机：记忆跟着 agent 走</a></li><li><a href="./chapters/19-isolation">第 19 章 记忆安全：跨 agent 隔离、沙箱与密钥</a></li><li><a href="./chapters/20-observability">第 20 章 观察与调试记忆：Memory Palace、/doctor 与审计</a></li><li><a href="./chapters/lab-6-palace">Lab 6 mini-letta v1.0：多机同步、隔离、Palace 与部署</a></li></ul><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><ul><li><a href="./appendix/a-source-map">A 源码地图（概念 → 路径）</a></li><li><a href="./appendix/b-glossary">B 术语表</a></li><li><a href="./appendix/c-comparison">C 横向对比：Letta 服务器 / 抽取式记忆 / 通用存储 / Claude Code 项目记忆</a></li><li><a href="./appendix/d-answers">D 练习参考答案</a></li></ul>',21)])])}const f=t(l,[["render",o]]);export{m as __pageData,f as default};
